const ExcelJS = require('exceljs');

async function createFlightRecord() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Travel Expenses');

  // Define columns
  sheet.columns = [
    { header: 'Flight Number', key: 'flightNumber', width: 16 },
    { header: 'From',          key: 'from',         width: 10 },
    { header: 'To',            key: 'to',           width: 10 },
    { header: 'Date',          key: 'date',         width: 14 },
    { header: 'Time',          key: 'time',         width: 10 },
  ];

  // Bold header row
  sheet.getRow(1).font = { bold: true };

  // Add the flight record
  sheet.addRow({
    flightNumber: 'FL6BD665',
    from: 'LAX',
    to: 'SFO',
    date: '2026-09-05',
    time: '09:00',
  });

  await workbook.xlsx.writeFile('skills/OfficeBench/testbed/data/travel_expenses.xlsx');
  console.log('File created successfully!');
}

createFlightRecord().catch(console.error);
